-- SUS-SP — R1 Acesso Direto: 600 questões, 600 classificadas
-- Fonte: Relatório "Análise das provas R1 da SUS-SP (2021-2026)" e planilha de classificação questão a questão; reponderação para 2027 ("SUS-SP R1 - análise reponderada para 2027 (banca VUNESP)")
-- Gerado por scripts/build-data-sql.mjs (não edite à mão). Pode rodar mais de uma vez.
-- =====================================================================

insert into public.institutions (name, abbreviation, state, city) values ('Processo Seletivo Unificado SUS-SP (Secretaria de Estado da Saúde de São Paulo)', 'SUS-SP', 'SP', 'São Paulo')
on conflict (abbreviation) do update set name = excluded.name, state = excluded.state, city = excluded.city;

insert into public.exams (institution_id, name, total_questions)
select id, 'R1 Acesso Direto', 100 from public.institutions where abbreviation = 'SUS-SP'
on conflict (institution_id, name) do update set total_questions = excluded.total_questions;

